  public string SearchText{get{return Group+" "+Keys+" "+Title+" "+Description;}}
  public static readonly KeybindHelp[] All={
   new KeybindHelp("In-game options","Ctrl+Shift+F12","Open graphics options","Open the in-game Quick Controls and other graphics sections. Escape closes the panel."),
