   new KeybindHelp("Graphics switches","Ctrl+Shift+F2","Generated bump maps","Toggle the generated surface relief effect."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+F3","Ambient occlusion","Toggle shading in creases and where nearby surfaces meet."),
