   new KeybindHelp("Graphics switches","Ctrl+Shift+F5","HDR scene rendering","Toggle the renderer's extended lighting range and tone mapping. This does not switch Windows display HDR."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+F6","Point-light shadows","Toggle shadows cast by nearby local lights."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+F7","Sun shadows","Toggle directional shadows from the sun."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+F8","Nearby lights","Toggle the extended nearby-light lighting path."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+F10","Per-pixel lighting","Toggle smoother lighting calculated across surfaces rather than only at their vertices."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+B","Material lighting","Toggle physically based material response, including roughness and metal reflections."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+D","Depth of field","Toggle focus blur. Its near/far/focus settings control which areas blur."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+G","Indirect light","Toggle the screen-space bounced-light effect."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+M","Motion blur","Toggle motion blur."),
