   new KeybindHelp("Graphics switches","Ctrl+Shift+T","Temporal anti-aliasing","Toggle anti-aliasing that combines information across frames to reduce edge shimmer."),
   new KeybindHelp("Graphics switches","Ctrl+Shift+V","Volumetric light","Toggle light scattered through air, including visible light shafts."),
   new KeybindHelp("Strength adjustments","Ctrl+Shift+[ / ]","Bump strength","The left bracket decreases and the right bracket increases generated bump strength by 0.25. These physical bracket keys can have different labels on other layouts."),
   new KeybindHelp("Strength adjustments","Ctrl+Shift+End / Home","Bloom strength","End decreases and Home increases bloom strength by 0.25."),
   new KeybindHelp("Strength adjustments","Ctrl+Shift+Delete / Insert","Effect glow strength","Delete decreases and Insert increases the glow of effects by 0.25."),
   new KeybindHelp("Strength adjustments","Ctrl+Shift+Page Down / Page Up","Local light headroom","Page Down decreases and Page Up increases local-light brightness headroom by 0.25."),
   new KeybindHelp("Capture and diagnostics","Ctrl+Shift+F9","Capture a diagnostic frame","Save a screenshot and a detailed frame report beside the renderer log in the selected AO folder. Useful when reporting visual problems."),
   new KeybindHelp("Capture and diagnostics","Ctrl+Shift+Alt+F9","Capture a frame sequence","Record 60 frames of draw information for deeper troubleshooting. This produces much more diagnostic data."),
   new KeybindHelp("Capture and diagnostics","Ctrl+Shift+H","Hide AO's interface","Hide or restore the game's interface for screenshots. This is temporary."),
   new KeybindHelp("Capture and diagnostics","Ctrl+Shift+I","Identify a texture","Pick the surface under the mouse, copy its texture ID to the clipboard, record its details in the log and briefly highlight its matching surfaces."),
   new KeybindHelp("Capture and diagnostics","Ctrl+Shift+J","Identify a model","Pick the model under the mouse and copy its ID for troubleshooting or artwork work."),
   new KeybindHelp("Capture and diagnostics","Ctrl+Shift+K","Material diagnostic views","Cycle material-map coverage, emission, reflections, roughness, metalness and other views, then Off. Enables material lighting; cycle back to Off for the normal picture."),
