   new KeybindHelp("Free camera","W / S / A / D","Move the camera","Move forward/backward with W/S and sideways with A/D."),
   new KeybindHelp("Free camera","E / Q","Move up / down","Raise or lower the free camera."),
   new KeybindHelp("Free camera","Shift / Mouse wheel","Change camera speed","Hold Shift to move four times faster. Scroll the wheel to adjust the base travel speed."),
