   new KeybindHelp("Console","Up / Down","Command history","Browse previously entered commands."),
   new KeybindHelp("Console","Page Up / Page Down","Console history","Scroll earlier output in the console."),
   new KeybindHelp("Travel screens","Click / a fresh key press","Continue after travel","When Click to continue is enabled and the zone is ready, click or press a new non-modifier key to dismiss the loading picture. Holding a key through travel does not dismiss it.")
